function GlassKilnBrickSawMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnBrickSawMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnBrickSawMaker.ironStock=GlassKilnBrickSawMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnBrickSawMaker.bronzeStock=GlassKilnBrickSawMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnBrickSawMaker.woodStock=GlassKilnBrickSawMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnBrickSawMaker.leatherStock=GlassKilnBrickSawMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnBrickSawMaker.silverStock=GlassKilnBrickSawMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnBrickSawMaker.goldStock=GlassKilnBrickSawMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnBrickSawMaker.jewelStock=GlassKilnBrickSawMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnBrickSawMaker.pearlStock=GlassKilnBrickSawMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnBrickSawMaker.maker then t=math.max(1,t-math.floor(GlassKilnBrickSawMaker.maker.skill/13)) end; table.insert(GlassKilnBrickSawMaker.activeMaking,{id="glasskilnbricksaw_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnBrickSawMaker.completeMaking(m) local q=1.0+(GlassKilnBrickSawMaker.getQualityBonus()/100); if GlassKilnBrickSawMaker.maker then q=q+(GlassKilnBrickSawMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnBrickSawMaker.productStock[m.productType]=(GlassKilnBrickSawMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnBrickSawMaker.totalProducts=GlassKilnBrickSawMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnBrickSawMaker.maker then GlassKilnBrickSawMaker.maker.itemsMade=GlassKilnBrickSawMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnBrickSawMaker.maker.skill=math.min(100,GlassKilnBrickSawMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žaga izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnbricksaw.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnBrickSawMaker.update(dt) if not _G.state then return end; GlassKilnBrickSawMaker.dayTimer=GlassKilnBrickSawMaker.dayTimer+dt; if GlassKilnBrickSawMaker.dayTimer>=30 then GlassKilnBrickSawMaker.dayTimer=0; for i=#GlassKilnBrickSawMaker.activeMaking,1,-1 do local m=GlassKilnBrickSawMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnBrickSawMaker.completeMaking(m); table.remove(GlassKilnBrickSawMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnBrickSawMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnBrickSawMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
